function mh_shuffle(arr){const a=arr.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function mh_buildDeck(){mh_deck=mh_shuffle(MH_SCENES);mh_cycle++;if(mh_current&&mh_deck.length>1&&mh_deck[0].id===mh_current.scene.id){[mh_deck[0],mh_deck[1]]=[mh_deck[1],mh_deck[0]];}}
function mh_pickQ(scene){let st=mh_qState[scene.id];if(!st)st=mh_qState[scene.id]={deck:[],last:-1};if(!st.deck.length){st.deck=mh_shuffle(scene.qs.map((_,i)=>i));if(st.deck.length>1&&st.deck[0]===st.last)[st.deck[0],st.deck[1]]=[st.deck[1],st.deck[0]];}const idx=st.deck.shift();st.last=idx;return scene.qs[idx];}
function mh_next(){if(typeof isMiniGameActive==='function'&&!isMiniGameActive('mall-handle'))return;if(!mh_deck.length)mh_buildDeck();const scene=mh_deck.shift();mh_current={scene,q:mh_pickQ(scene)};mh_round++;mh_locked=false;mh_render();}
function mh_esc(s){return String(s).replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}
function mh_ensureStyles(){if(document.getElementById('mh-style'))return;const s=document.createElement('style');s.id='mh-style';s.textContent=`
@keyframes mhShake{0%,100%{transform:translateX(0)}25%{transform:translateX(-7px)}50%{transform:translateX(7px)}75%{transform:translateX(-4px)}}
@keyframes mhGlow{0%,100%{box-shadow:none}50%{box-shadow:0 0 30px rgba(249,115,22,.28)}}
.mh-shake{animation:mhShake .3s ease}.mh-correct{animation:mhGlow .65s ease}
.mh-layout{display:grid;grid-template-columns:minmax(300px,410px) minmax(0,1fr);gap:14px;align-items:stretch}.mh-picwrap{position:relative;aspect-ratio:1/1;width:100%;overflow:hidden;border-radius:22px}.mh-pic{width:100%;height:100%;object-fit:cover;display:block}.mh-opts{display:grid;grid-template-columns:1fr;gap:9px;align-content:center}.mh-opt{min-height:58px;text-align:left}
@media(max-width:900px){.mh-layout{grid-template-columns:minmax(260px,350px) minmax(0,1fr);gap:10px}.mh-opt{min-height:54px}}@media(max-width:700px){.mh-layout{grid-template-columns:1fr}.mh-picwrap{max-width:430px;margin:0 auto}.mh-opts{grid-template-columns:1fr}.mh-opt{min-height:50px}}`;
document.head.appendChild(s);}
function startMallHandleGame(){mh_ensureStyles();mh_deck=[];mh_round=0;mh_cycle=0;mh_score=0;mh_streak=0;mh_best=0;mh_locked=false;mh_current=null;mh_tokens=0;Object.keys(mh_qState).forEach(k=>delete mh_qState[k]);mh_next();}
function mh_render(){const box=document.getElementById('game-play-container');if(!box||!mh_current)return;const [question,correct,rawOptions,type,explain]=mh_current.q;const options=mh_shuffle(rawOptions);box.innerHTML=`
<div class="rounded-[28px] border-2 border-orange-200 bg-gradient-to-b from-orange-50/80 via-rose-50/45 to-yellow-50/50 p-2.5 md:p-3"><div class="flex items-center justify-between gap-2 mb-2"><div class="flex items-center gap-2 min-w-0"><span class="px-3 py-1.5 rounded-full bg-white/90 border-orange-200 text-orange-700 font-black text-xs md:text-sm shrink-0">🚨 Lượt ${mh_round}</span><span class="px-2.5 py-1 rounded-full bg-orange-100 text-orange-700 font-black text-[10px] md:text-xs">${mh_esc(type)}</span></div><div class="flex gap-1.5 shrink-0"><span class="px-2.5 py-1.5 rounded-full bg-amber-50 border border-amber-200 text-amber-700 font-black text-xs md:text-sm">⭐ ${mh_score}</span><span class="px-2.5 py-1.5 rounded-full bg-rose-50 border border-rose-200 text-rose-600 font-black text-xs md:text-sm">🔥 x${mh_streak}</span><span class="px-2.5 py-1.5 rounded-full bg-orange-50 text-orange-700 border border-orange-200 font-black text-xs md:text-sm">🛡️ ${mh_tokens}</span></div></div>
<div data-minigame-question class="mb-2 px-3 py-2 rounded-2xl bg-white/90 border-orange-200 text-center font-black text-slate-700 text-sm md:text-lg leading-snug">${mh_esc(question)}</div>
<div class="mh-layout"><div class="mh-picwrap"><img class="mh-pic" src="${mh_current.scene.image}" alt="Tranh trung tâm thương mại"></div><div class="mh-opts">${options.map((op,i)=>`<button class="mh-opt px-4 py-2.5 rounded-2xl border-2 ${['bg-white border-sky-200 hover:bg-sky-50','bg-white border-emerald-200 hover:bg-emerald-50','bg-white border-amber-200 hover:bg-amber-50','bg-white border-violet-200 hover:bg-violet-50'][i]} text-slate-700 font-extrabold text-sm md:text-[15px] leading-snug shadow-sm transition-all" data-answer="${mh_esc(op)}" onclick="mh_choose(this)">${mh_esc(op)}</button>`).join('')}<div id="mh-feedback" class="min-h-[34px] flex items-center justify-center text-center text-xs md:text-sm font-black text-orange-700">🧠 Bé đọc kỹ, suy nghĩ thật thoải mái rồi chọn cách xử lý phù hợp nhất nhé!</div></div></div></div>`;
if(typeof setMiniGameQuestionAudio==='function')setMiniGameQuestionAudio(question,0.92);if(typeof mhSpeakSafe==='function')setTimeout(()=>mhSpeakSafe(question,0.92),140);}
function mh_choose(btn){if(mh_locked||!mh_current)return;const answer=btn.dataset.answer;const correct=mh_current.q[1];const explain=mh_current.q[4]||'';if(answer===correct){mh_locked=true;mh_score+=12+Math.min(mh_streak,5)*2;mh_streak++;mh_best=Math.max(mh_best,mh_streak);mh_tokens++;btn.classList.add('bg-emerald-100','border-emerald-400','text-emerald-800','mh-correct');const fb=document.getElementById('mh-feedback');if(fb)fb.innerHTML=`🚨 Xử lý chuẩn! <span class="ml-1">${mh_esc(explain)}</span>`;if(typeof playAudio==='function')playAudio('correct');if(typeof confetti==='function')confetti({particleCount:55,spread:70,origin:{y:.72}});if(typeof mhSpeakSafe==='function')mhSpeakSafe('Chính xác! Bé xử lý tình huống rất tốt.',1.0);setTimeout(mh_next,1500);}else{mh_streak=0;btn.classList.add('mh-shake','border-rose-400','bg-rose-50');setTimeout(()=>btn.classList.remove('mh-shake','border-rose-400','bg-rose-50'),360);const fb=document.getElementById('mh-feedback');if(fb)fb.textContent='⚠️ Cách này chưa an toàn hoặc chưa phải việc nên làm trước. Bé thử lại nhé!';if(typeof playAudio==='function')playAudio('wrong');}}


window.startMallHandleGame=startMallHandleGame;window.mh_choose=mh_choose;
